<div class="card detail-card"><div class="detail-header"><div><h2><?=e($order['po_number'])?></h2><p class="muted">Purchase Order</p></div><span class="badge status-<?=strtolower($order['status'])?>"><?=e($order['status'])?></span></div><div class="detail-grid"><div><small>Supplier</small><strong><?=e($order['supplier_name'])?></strong></div><div><small>Gudang</small><strong><?=e($order['warehouse_name'])?></strong></div><div><small>Tanggal</small><strong><?=e($order['po_date'])?></strong></div><div><small>Total</small><strong>Rp <?=number_format((float)$order['total_amount'],0,',','.')?></strong></div></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody><?php foreach($order['details'] as $d):?><tr><td><?=e($d['product_code'].' - '.$d['product_name'])?></td><td><?=number_format((float)$d['qty'],2,',','.')?> <?=e($d['unit'])?></td><td>Rp <?=number_format((float)$d['price'],0,',','.')?></td><td>Rp <?=number_format((float)$d['subtotal'],0,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div>
